package com.nook.controller; import com.nook.dto.ApiDtos.ShopDto; import com.nook.service.*; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/coffee-shops") public class CoffeeShopController {final CoffeeShopService s;final GooglePlacesProvider google;public CoffeeShopController(CoffeeShopService s,GooglePlacesProvider google){this.s=s;this.google=google;}@GetMapping("/nearby") List<ShopDto> nearby(@RequestParam double latitude,@RequestParam double longitude,@RequestParam(defaultValue="10")double radiusKm){return s.nearby(latitude,longitude,Math.min(radiusKm,50));}@GetMapping("/photos/{token}") ResponseEntity<byte[]> photo(@PathVariable String token){return google.photo(token);}@GetMapping("/{id}") ShopDto one(@PathVariable UUID id,@RequestParam double latitude,@RequestParam double longitude){return s.one(id,latitude,longitude);}}
